 "content": "def transform(grid):
    """Move the motif adjacent to its rail and mark the pre-move leading edge."""
    from collections import Counter

    h, w = len(grid), len(grid[0])
    border = grid[0] + grid[-1] + [grid[r][0] for r in range(h)] + [grid[r][-1] for r in range(h)]
    bg = Counter(border).most_common(1)[0][0]

    # Locate a full uniform non-background rail line.
    rail = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != bg:
            rail = ("row", r, row[0])
            break
    if rail is None:
        for c in range(w):
            col = [grid[r][c] for r in range(h)]
            if len(set(col)) == 1 and col[0] != bg:
                rail = ("col", c, col[0])
                break
    if rail is None:
        return [row[:] for row in grid]

    axis, pos, rail_color = rail
    obj = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != rail_color]
    if not obj:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    if axis == "col":
        left, right = min(c for _, c, _ in obj), max(c for _, c, _ in obj)
        if right < pos:
            shift = pos - right - 1
            moved = [(r, c + shift, v) for r, c, v in obj]
            trail = left + shift - 1
        else:
            shift = left - pos - 1
            moved = [(r, c - shift, v) for r, c, v in obj]
            trail = right - shift + 1
        for r, c, _ in obj:
            out[r][c] = bg
        for r, c, v in moved:
            out[r][c] = v
        if 0 <= trail < w:
            for r in range(h):
                # The 8 stripe fills the line just behind the moved motif,
                # except where the original rail crosses it.
                out[r][trail] = bg if grid[r][trail] == pos and grid[r][trail] != bg else 8
    else:
        top, bottom = min(r for r, _, _ in obj), max(r for r, _, _ in obj)
        if bottom < pos:
            shift = pos - bottom - 1
            moved = [(r + shift, c, v) for r, c, v in obj]
            trail = top + shift - 1
        else:
            shift = top - pos - 1
            moved = [(r - shift, c, v) for r, c, v in obj]
            trail = bottom - shift + 1
        for r, c, _ in obj:
            out[r][c] = bg
        for r, c, v in moved:
            out[r][c] = v
        if 0 <= trail < h:
            out[trail] = [8] * w
    return out

